pub const rules = [_]Rule{
    .{ .name = "sjis-eudc", .text = "Shift_JIS decoder: pointers 8836..10715 (lead 0xF0-0xF9) are EUDC, code point 0xE000 - 8836 + pointer (Go: U+FFFD)." },
    .{ .name = "ascii-trail-restore", .text = "Decoders of Shift_JIS/Big5/gb18030: an ASCII byte that fails as a trail byte is `restore`d to the stream (it is decoded on its own after the U+FFFD); Go swallows it." },
    .{ .name = "nonascii-trail-consumed", .text = "Decoders of EUC-JP/gb18030: a non-ASCII byte that fails as a trail byte is consumed with the lead byte: ONE U+FFFD (Go emits two)." },
    .{ .name = "gb-user-defined", .text = "gb18030 index: 0xA140-0xA7A0, 0xAAA1-0xAFFE, 0xF8A1-0xFEFE map to Private Use code points (Go: U+FFFD)." },
    .{ .name = "gb-2022-two-byte", .text = "gb18030 index (GB18030-2022): 0xA6D9..0xA6F3, 0xA8BC, 0xFE50..0xFEA0 map to U+FE10.., U+1E3F, U+9FB4.. as two bytes (Go: U+FFFD)." },
    .{ .name = "gb-truncated-four-byte", .text = "gb18030 decoder: a four-byte form cut short (lead, digit, ...) at the end of the input is ONE error (end-of-queue with first/second/third set); Go emits U+FFFD then the digit." },
    .{ .name = "gb-four-byte-gap", .text = "gb18030 ranges: a four-byte pointer in 39420..188999 (or > 1237575) has no code point: ONE error consuming all four bytes (Go re-reads the digits)." },
    .{ .name = "gb-e7c7", .text = "gb18030 ranges: pointer 7457 is U+E7C7 (the 2005 change handled inline); Go: U+1E3F." },
    .{ .name = "iso-so-si", .text = "ISO-2022-JP decoder: 0x0E and 0x0F are errors in the ASCII, Roman, katakana and lead-byte states (Go passes them through)." },
    .{ .name = "iso-escape-recovery", .text = "ISO-2022-JP decoder: an escape that is not one of the five known ones is an error and its bytes are restored; a repeated or interrupted escape is an error (Go differs in how many bytes the error swallows)." },
    .{ .name = "e-sjis-special", .text = "Shift_JIS encoder: U+0080 -> 0x80, U+00A5 -> 0x5C, U+203E -> 0x7E, U+2212 -> U+FF0D (Go: unmappable)." },
    .{ .name = "e-sjis-nec-ibm", .text = "index Shift_JIS pointer: pointers 8272..8835 (NEC-selected IBM extensions, rows 0xED/0xEE) are excluded, so the IBM extension rows 0xFA-0xFC are used (Go: 0xED/0xEE)." },
    .{ .name = "e-eucjp-special", .text = "EUC-JP encoder: U+00A5 -> 0x5C, U+203E -> 0x7E, U+2212 -> U+FF0D (Go: unmappable)." },
    .{ .name = "e-eucjp-no-jis0212", .text = "EUC-JP encoder uses index jis0208 only: a character only in jis0212 is unmappable (Go writes 0x8F + two bytes)." },
    .{ .name = "e-iso-special", .text = "ISO-2022-JP encoder: U+00A5/U+203E switch to the Roman state (ESC ( J), U+2212 -> U+FF0D (Go: unmappable)." },
    .{ .name = "e-iso-controls", .text = "ISO-2022-JP encoder: U+000E, U+000F, U+001B are an error (with U+FFFD) in the ASCII and Roman states (Go passes them)." },
    .{ .name = "e-iso-katakana", .text = "ISO-2022-JP encoder: U+FF61..U+FF9F are mapped through index ISO-2022-JP katakana to full-width and written in the jis0208 state (Go: ESC ( I half-width)." },
    .{ .name = "e-gb-e5e5", .text = "gb18030 encoder: U+E5E5 is an error (0xA3 0xA0 decodes to U+3000, so it cannot round-trip); Go writes a four-byte form." },
    .{ .name = "e-gb-two-byte", .text = "gb18030 encoder: the side table (Private Use code points of GB18030-2022) and index gb18030 give these two bytes; Go writes four bytes (gb18030) or nothing (GBK)." },
    .{ .name = "e-big5-hkscs", .text = "index Big5 pointer: pointers below (0xA1 - 0x81) * 157 (the HKSCS extension) are excluded from the encoder (Go encodes them)." },
    .{ .name = "e-big5-duplicate", .text = "index Big5 pointer: for a duplicated code point the FIRST pointer is used (Go: the last), except U+2550, U+255E, U+2561, U+256A, U+5341, U+5345 (last)." },
    .{ .name = "random-composite", .text = "A random input; every divergence contains at least one construct of the classes above, not attributed individually." },
};

